// decodePrefix parses as many whole records as a possibly-truncated output
// contains, returning them together with the unconsumed trailing bytes
// (which a write interruption is allowed to leave mid-record).
func decodePrefix(t *testing.T, data []byte) ([]map[string]any, []byte) {
	t.Helper()
	var results []map[string]any
	dec := json.NewDecoder(bytes.NewReader(data))
	for {
		var m map[string]any
		if err := dec.Decode(&m); err != nil {
			if errors.Is(err, io.EOF) {
				t.Fatalf("expected truncated trailing output, got a clean record boundary")
			}
			return results, data[dec.InputOffset():]
		}
		results = append(results, m)
	}
}

